    "Սոնետ 3": {"hy":"Հայելու մեջ մոր դեմքը՝ կոչ ունենալու զավակ","en":"Sonnet 3","ru":"Сонет 3"},
    "Սոնետ 4": {"hy":"Անշահախնդիր վատնված գեղեցկություն","en":"Sonnet 4","ru":"Сонет 4"},
