    "Սոնետ 8": {"hy":"Երաժշտության ներդաշնակությունը՝ ընտանիքի խորհրդանիշ","en":"Sonnet 8","ru":"Сонет 8"},
    "Սոնետ 9": {"hy":"Այրու արցունքի վախը՝ մենակության դեմ","en":"Sonnet 9","ru":"Сонет 9"},
